def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_def = 0
    opp_c = 0
    seen_nonpunish = False
    cd_total = 0

    for i in range(n):
        m, o = history[i]
        if o == 'D':
            opp_def += 1
        else:
            opp_c += 1

        if i > 0:
            prev_me = history[i - 1][0]
            if prev_me == 'D':
                if o == 'C':
                    seen_nonpunish = True
            else:
                if o == 'D':
                    cd_total += 1

    r10 = sum(1 for _, o in history[-10:] if o == 'D')
    r20 = sum(1 for _, o in history[-20:] if o == 'D')

    cd_recent = 0
    if n > 1:
        start = max(1, n - 10)
        for i in range(start, n):
            if history[i - 1][0] == 'C' and history[i][1] == 'D':
                cd_recent += 1

    opp_d_streak = 0
    if last_opp == 'D':
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                opp_d_streak += 1
            else:
                break

    opp_c_streak = 0
    if last_opp == 'C':
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'C':
                opp_c_streak += 1
            else:
                break

    period = 0
    if r20 >= 4 and n >= 12:
        for p in range(2, 8):
            if n >= 2 * p:
                start = max(p, n - 20)
                cnt = 0
                match = 0
                for i in range(start, n):
                    cnt += 1
                    if history[i][1] == history[i - p][1]:
                        match += 1
                if cnt >= 10 and match * 100 >= cnt * 85:
                    period = p
                    break

    if seen_nonpunish and opp_def <= 2 and r10 == 0 and last_opp == 'C':
        return 'D'

    if opp_def == 0:
        if last_me == 'D' and last_opp == 'C' and not seen_nonpunish:
            return 'C'
        if n >= 30 and last_opp == 'C' and last_me == 'C' and opp_c_streak >= 20 and n < 95:
            return 'D'

    if opp_c <= 2 and n >= 8:
        return 'D'

    if period and r20 >= 4 and opp_def * 4 >= n and opp_d_streak < 5:
        return 'D'

    if last_opp == 'C':
        if r10 >= 8:
            return 'D'
        if opp_c_streak >= 8 and n < 90 and rng.randint(0, 11) == 0:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if last_me == 'C' and cd_recent >= 5:
            return 'D'

        if cd_total >= 8 and opp_def * 10 >= n * 3:
            return 'D'

        if opp_d_streak >= 5:
            if rng.random() < 0.25:
                return 'C'
            return 'D'

        if opp_def * 20 > n * 7:
            return 'D'

        return 'C'

    return 'C'
